import { RendererCanvas } from '../../../lib'

export class Solution {
    public divHost: HTMLElement;
    public renderer: Renderer;
    constructor(id: string) {
        this.divHost = document.getElementById(id)

        // Center align
        this.divHost.style.display = 'flex';
        this.divHost.style.alignItems = 'center';

        const div = document.createElement('div');
        div.style.marginLeft = 'auto';
        div.style.marginRight = 'auto';
        div.style.backgroundColor = '#555';
        div.style.width = '1000px';
        div.style.height = '600px';

        this.divHost.appendChild(div);

        // TODO
        // You code goes here for one time operation

        this.renderer = new Renderer(div);

        // console.log(this.renderer);
        // !! you should execute it for rendering
        // this.start();
    }
    public destroy() {
        if (this.divHost) {
            try {
                while (this.divHost.firstChild) {
                    this.divHost.removeChild(this.divHost.firstChild);
                }
            } catch (error) {
                console.error('Error in destroy method:', error);
            }
        } else {
            console.warn('divHost is undefined in destroy method');
        }
    }
}



export class Renderer extends RendererCanvas {
    private prevFrame?: ImageData;
    private video: HTMLVideoElement;
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;
    private skip = 8; // Grid density
    private flowScale = 8.0; // Increased vector scale for more dramatic effect
    private threshold = 10; // Motion sensitivity
    private lineParams = {
        minLength: 2,
        maxLength: 50, // Increased max length
        width: 1.5,
        opacity: 0.8
    };
    
    constructor(div: any) {
        super(div);
        this.canvas.style.position = 'relative';
        this.canvas.style.width = '100%';
        this.canvas.style.height = '100%';
        
        // Set up video input
        this.video = document.createElement('video');
        this.video.autoplay = true;
        this.video.style.display = 'none';
        document.body.appendChild(this.video);
        
        // Set up temp canvas for processing
        this.tempCanvas = document.createElement('canvas');
        this.tempCtx = this.tempCanvas.getContext('2d')!;
        
        // Get camera access
        navigator.mediaDevices.getUserMedia({ 
            video: { 
                width: { ideal: 1280 },
                height: { ideal: 720 }
            } 
        }).then(stream => {
            this.video.srcObject = stream;
            this.video.onloadedmetadata = () => {
                const w = this.video.videoWidth;
                const h = this.video.videoHeight;
                this.canvas.width = w;
                this.canvas.height = h;
                this.tempCanvas.width = w;
                this.tempCanvas.height = h;
            };
        });
        
        this.start();
    }
    
    public render(ctx: CanvasRenderingContext2D): void {
        const w = this.canvas.width;
        const h = this.canvas.height;
        if (!w || !h) return;
        
        // Draw camera background
        ctx.drawImage(this.video, 0, 0, w, h);
        
        // Get current frame
        this.tempCtx.drawImage(this.video, 0, 0, w, h);
        const curr = this.tempCtx.getImageData(0, 0, w, h);
        
        // First frame case
        if (!this.prevFrame) {
            this.prevFrame = curr;
            return;
        }
        
        // Draw grid of dots
        ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
        for (let y = 0; y < h; y += this.skip) {
            for (let x = 0; x < w; x += this.skip) {
                ctx.beginPath();
                ctx.arc(x, y, 1, 0, Math.PI * 2);
                ctx.fill();
            }
        }
        
        // Calculate and draw flow lines
        for (let y = 0; y < h; y += this.skip) {
            for (let x = 0; x < w; x += this.skip) {
                const idx = (y * w + x) * 4;
                
                // Calculate difference between frames
                const rDiff = curr.data[idx] - this.prevFrame.data[idx];
                const gDiff = curr.data[idx + 1] - this.prevFrame.data[idx + 1];
                const bDiff = curr.data[idx + 2] - this.prevFrame.data[idx + 2];
                
                // Calculate magnitude and direction
                const mag = Math.sqrt(rDiff * rDiff + gDiff * gDiff + bDiff * bDiff);
                
                if (mag > this.threshold) {
                    // Normalize and scale the vector
                    const dx = (rDiff / mag) * Math.min(mag * this.flowScale, this.lineParams.maxLength);
                    const dy = (gDiff / mag) * Math.min(mag * this.flowScale, this.lineParams.maxLength);
                    
                    // Only draw if magnitude is significant
                    if (Math.abs(dx) > this.lineParams.minLength || Math.abs(dy) > this.lineParams.minLength) {
                        // Draw flow line
                        ctx.beginPath();
                        ctx.moveTo(x, y);
                        ctx.lineTo(x + dx, y + dy);
                        
                        // Set line style based on magnitude
                        const intensity = Math.min(1, mag / 100);
                        ctx.strokeStyle = `rgba(0, 0, 0, ${intensity * this.lineParams.opacity})`;
                        ctx.lineWidth = this.lineParams.width;
                        ctx.stroke();
                    }
                }
            }
        }
        
        // Update previous frame
        this.prevFrame = curr;
    }
}


